/** Trusted React renderer for this Rich Catalog component. */
import React from "react"; import {useRichComponent} from "../../../binding.js"; export function Renderer({surface,component,basePath="/"}){const {properties:p}=useRichComponent(surface,component,basePath);const d=p.data??[],total=d.reduce((s,x)=>s+x.value,0)||1;let offset=0;return <figure className="anu-rich-chart donut"><figcaption><strong>{p.title}</strong></figcaption><div className="donut-wrap"><svg viewBox="0 0 42 42" role="img" aria-label={p.title}>{d.map((x,i)=>{const pct=x.value/total*100,o=offset;offset+=pct;return <circle key={x.label} cx="21" cy="21" r="15.9" fill="none" pathLength="100" strokeDasharray={`${pct} ${100-pct}`} strokeDashoffset={-o} className={`slice-${i%6}`}/>})}</svg>{p.centerLabel&&<strong>{p.centerLabel}</strong>}</div><ul>{d.map((x,i)=><li key={x.label}><i className={`slice-${i%6}`}/>{x.label}<b>{x.value}</b></li>)}</ul></figure>}
